const _ROWS = BATCH71_KYR6_AMAZON_3P_NOW;
if (_ROWS.length !== 705) throw new Error('batch71 tally drift: expected 705 rows');
if (_ROWS.filter((r) => r.verdict === 'clean').length !== 201) {
  throw new Error('batch71 Clean tally drift');
}
if (_ROWS.filter((r) => r.verdict === 'caution').length !== 482) {
  throw new Error('batch71 Caution tally drift');
}
if (_ROWS.filter((r) => r.verdict === 'avoid').length !== 22) {
  throw new Error('batch71 Avoid tally drift');
}
if (_ROWS.some((r) => r.recordStatus !== UNVERIFIED)) {
  throw new Error('batch71 recordStatus must stay unverified');
}
if (_ROWS.some((r) => !r.formulaId)) {
  throw new Error('batch71 every row needs formulaId');
}
const _ids = new Set(_ROWS.map((r) => r.id));
if (_ids.size !== _ROWS.length) throw new Error('batch71 duplicate ids');
if (_ids.has('now-turmeric-curcumin-bioperine')) {
  throw new Error('batch71 must not clone already-on-MAIN turmeric BioPerine');
}
if (_ROWS.some((r) => r.brand !== BRAND)) {
  throw new Error('batch71 writes NOW only');
}
if (_ROWS.some((r) => r.barcode && !/^733739\d{6}$/.test(r.barcode))) {
  throw new Error('batch71 invented or non-NOW UPC');
}
if (_ROWS.filter((r) => r.formulaId !== r.id).length !== 101) {
  throw new Error('batch71 REUSE-formula tally drift');
}
if (!BATCH71_SKIPPED.some((s) => /already-on-MAIN/i.test(s.reason))) {
  throw new Error('batch71 must skip already-on-MAIN turmeric');
}
if (!BATCH71_REFUSED.some((s) => /Vegetarian Coating/i.test(s.reason))) {
  throw new Error('batch71 must refuse Vegetarian Coating (not exact Vegetable Coating)');
}
if (_ROWS.some((r) => /essential oils?,/i.test(r.productName))) {
  throw new Error('batch71 must not grade EO pour bottles');
}
for (const record of _ROWS) {
  if (record.verdict === 'avoid' && !record.inactiveIngredients.some((i) => i.riskLevel === 'high')) {
    if (!/caramel|talc|titanium|dye|seed oil/i.test(record.honestNote || '')) {
      throw new Error(`batch71 Avoid without High on ${record.id}`);
    }
  }
}
